module pipeline_register (
    input clk,
    input rst,
    input [7:0] data_in,
    output reg [7:0] data_out
);
    reg [7:0] stage [0:6];

    integer i;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < 7; i = i + 1) begin
                stage[i] <= 8'b0;
            end
            data_out <= 8'b0;
        end else begin
            stage[0] <= data_in;
            for (i = 1; i < 7; i = i + 1) begin
                stage[i] <= stage[i - 1];
            end
            data_out <= stage[6];
        end
    end
endmodule

