module rc_oscillator(  
    input wire clk,  
    input wire reset,  
    output reg out  
);  
    reg [31:0] counter;  
    parameter LIMIT = 50000000; // Adjust based on desired frequency  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            out <= 0;  
        end else begin  
            if (counter >= LIMIT) begin  
                out <= ~out;  
                counter <= 0;  
            end else begin  
                counter <= counter + 1;  
            end  
        end  
    end  
endmodule

