module cnn_convolution (
    input clk,
    input rst_n,
    input [15:0] input_matrix, // 4x4 input matrix flattened
    input [8:0] kernel, // 3x3 kernel flattened
    output reg [7:0] output_feature_map // 2x2 output feature map flattened
);
    reg [7:0] conv_result [0:3]; // Temporary storage for convolution results
    integer i, j;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            output_feature_map <= 0;
            conv_result[0] <= 0;
            conv_result[1] <= 0;
            conv_result[2] <= 0;
            conv_result[3] <= 0;
        end else begin
            // Compute convolution
            for (i = 0; i < 2; i = i + 1) begin
                for (j = 0; j < 2; j = j + 1) begin
                    conv_result[i * 2 + j] <= (input_matrix[i * 4 + j] * kernel[0] + 
                                                input_matrix[i * 4 + j + 1] * kernel[1] + 
                                                input_matrix[(i + 1) * 4 + j] * kernel[3] + 
                                                input_matrix[(i + 1) * 4 + j + 1] * kernel[4]);
                    conv_result[i * 2 + j] <= (conv_result[i * 2 + j] > 0) ? conv_result[i * 2 + j] : 0; // ReLU
                end
            end
            output_feature_map <= {conv_result[0], conv_result[1], conv_result[2], conv_result[3]};
        end
    end
endmodule

module RSA_Encryptor(  
    input wire clk,  
    input wire rst,  
    input wire [31:0] plaintext,  
    input wire [31:0] n,  
    input wire [31:0] e,  
    output reg [31:0] ciphertext,  
    output reg done  
);  
    reg [3:0] state;  
    parameter IDLE = 4'b0000,  
              COMPUTE = 4'b0001,  
              OUTPUT = 4'b0010;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            state <= IDLE;  
            ciphertext <= 0;  
            done <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (plaintext != 0) begin  
                        state <= COMPUTE;  
                        done <= 0;  
                    end  
                end  
                COMPUTE: begin  
                    // Simple modular exponentiation (for example purposes)  
                    ciphertext <= (plaintext ** e) % n;  
                    state <= OUTPUT;  
                end  
                OUTPUT: begin  
                    done <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

