module uart_transmitter (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire [7:0] data_in,
    output reg tx,
    output reg tx_done
);
    parameter BAUD_RATE = 115200;
    parameter CLOCK_FREQ = 50000000; // 50MHz
    localparam BIT_PERIOD = CLOCK_FREQ / BAUD_RATE;

    reg [3:0] bit_index;
    reg [15:0] clk_count;
    reg transmitting;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1; // Idle state is high
            tx_done <= 0;
            bit_index <= 0;
            clk_count <= 0;
            transmitting <= 0;
        end else if (enable && !transmitting) begin
            transmitting <= 1;
            tx <= 0; // Start bit
            bit_index <= 0;
            clk_count <= 0;
            tx_done <= 0;
        end else if (transmitting) begin
            if (clk_count < BIT_PERIOD - 1) begin
                clk_count <= clk_count + 1;
            end else begin
                clk_count <= 0;
                if (bit_index < 8) begin
                    tx <= data_in[bit_index]; // Send data bits
                    bit_index <= bit_index + 1;
                end else if (bit_index == 8) begin
                    tx <= 1; // Stop bit
                    bit_index <= bit_index + 1;
                end else begin
                    transmitting <= 0; // Finish transmission
                    tx_done <= 1;
                end
            end
        end
    end
endmodule

