module dma_controller(  
    input wire clk,  
    input wire reset,  
    input wire start,  
    input wire [3:0] channel_select,  
    output reg busy,  
    output reg done  
);  
    reg [3:0] state;  
    parameter IDLE = 4'b0001,  
              TRANSFER = 4'b0010,  
              DONE = 4'b0100;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            state <= IDLE;  
            busy <= 0;  
            done <= 0;  
        end else begin  
            case (state)  
                IDLE: begin  
                    if (start) begin  
                        busy <= 1;  
                        done <= 0;  
                        state <= TRANSFER;  
                    end  
                end  
                TRANSFER: begin  
                    // Simulate data transfer for the selected channel  
                    // This is just a simple simulation, in actual DMA it would involve more logic  
                    state <= DONE;  
                end  
                DONE: begin  
                    busy <= 0;  
                    done <= 1;  
                    state <= IDLE;  
                end  
            endcase  
        end  
    end  
endmodule

