module audio_compressor (
    input wire clk,
    input wire reset,
    input wire [7:0] audio_sample,
    output reg [7:0] compressed_sample
);
    reg [7:0] sample_reg;
    reg [1:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            sample_reg <= 8'b0;
            count <= 2'b0;
            compressed_sample <= 8'b0;
        end else begin
            if (count == 2'b00) begin
                sample_reg <= audio_sample;
                count <= count + 1;
            end else if (count == 2'b01) begin
                compressed_sample <= (sample_reg + audio_sample) >> 1;
                count <= 2'b00; // Reset count for next pair
            end
        end
    end
endmodule

